75	// Compile-time cluster volume from the tuned shape, capped at the Hopper
76	// portable max (8). Used both for the host-side fits-in-one-cluster decision
77	// and to bound the DSMEM gather. (The __cluster_dims__ attribute below takes
78	// the three scalar components directly.)
79	namespace prodigy_detail {
80	constexpr int kRawClusterVolume = SG_TUNED_CLUSTER_SHAPE_VOLUME;
81	constexpr int kClusterVolume =
82	    (kRawClusterVolume > 8) ? 8 : kRawClusterVolume;
83	}  // namespace prodigy_detail
