85	template <typename ParamT, typename GradT>
86	__global__ void __launch_bounds__(SG_TUNED_BLOCK_SIZE, SG_PRODIGY_MIN_BLOCKS)
87	prodigy_reduce_kernel(
88	    const ParamT* param, const ParamT* param_init, const GradT* grad,
89	    float d_prev,
90	    float* r_partial, float* s_partial,
91	    int64_t N
92	) {
93	    float r_local = 0.0f, s_local = 0.0f;
94	    const int64_t stride = prim::grid_stride();
95	    for (int64_t i = prim::grid_stride_index(); i < N; i += stride) {
96	        SG_SANITIZE_GRAD_INPLACE(grad, i);
97	        prodigy_partials_step(param, param_init, grad, d_prev, i,
98	                              r_local, s_local);
99	    }
100	    // Single fused two-value block reduction (one shared tile + one barrier
101	    // pair) → ONE atomicAdd per partial per block, instead of two separate
102	    // block reductions.
103	    float r_block, s_block;
104	    prim::block_reduce_sum2_f32(r_local, s_local, r_block, s_block);
105	    if (threadIdx.x == 0) {
106	        atomicAdd(r_partial, r_block);
107	        atomicAdd(s_partial, s_block);
108	    }
109	}
110	
111	// Fused reduce + d-update for the SINGLE-tensor path: the LAST block to finish
112	// (last_block_finished + the gridDim counter) reads the fully-accumulated
113	// (r, s) partials and writes d_t directly — folding away the separate
114	// <<<1,1>>> prodigy_update_d_kernel launch. block_done_counter must be a
115	// device scalar zeroed before launch. The multi-tensor path keeps the separate
116	// d-update kernel (it accumulates across many launches before the update).
117	template <typename ParamT, typename GradT>
118	__global__ void __launch_bounds__(SG_TUNED_BLOCK_SIZE, SG_PRODIGY_MIN_BLOCKS)
119	prodigy_reduce_and_update_d_kernel(
120	    const ParamT* param, const ParamT* param_init, const GradT* grad,
121	    float d_prev,
122	    float* r_partial, float* s_partial, float* d_t,
123	    unsigned* block_done_counter,
124	    int64_t N, int total_blocks
125	) {
126	    float r_local = 0.0f, s_local = 0.0f;
127	    const int64_t stride = prim::grid_stride();
128	    for (int64_t i = prim::grid_stride_index(); i < N; i += stride) {
129	        SG_SANITIZE_GRAD_INPLACE(grad, i);
130	        prodigy_partials_step(param, param_init, grad, d_prev, i,
131	                              r_local, s_local);
132	    }
133	    float r_block, s_block;
134	    prim::block_reduce_sum2_f32(r_local, s_local, r_block, s_block);
135	    if (threadIdx.x == 0) {
136	        atomicAdd(r_partial, r_block);
137	        atomicAdd(s_partial, s_block);
138	    }
139	    // __threadfence so the last block sees the completed atomic results.
140	    __threadfence();
141	    if (prim::last_block_finished(block_done_counter, total_blocks)) {
142	        if (threadIdx.x == 0) {
143	            *d_t = prodigy_update_d(d_prev, *r_partial, *s_partial);
144	        }
145	    }
146	}
147	
148	// §3.2 DSMEM cluster variant of the (r, s) partial reduce. Launched with a
149	// thread-block cluster (__cluster_dims__) so the whole reduction fits in ONE
150	// cluster; the cross-block sum is done via DSMEM (map_shared_rank + cl.sync)
151	// instead of a global atomicAdd. Only correct when the launch grid == the
152	// cluster volume (one cluster covers every block); the host launcher enforces
153	// that before selecting this kernel. Block 0 writes the final sum directly.
154	//
155	// Gated behind ENABLE_DSMEM_REDUCE at the call site; when the toggle is off,
156	// this kernel is never launched (the atomic kernel above is used) — so the
157	// cluster machinery adds NO cost on the default path.
158	#if defined(ENABLE_DSMEM_REDUCE) && (ENABLE_DSMEM_REDUCE != 0)
159	template <typename ParamT, typename GradT>
160	__global__ void __cluster_dims__(
161	    SG_TUNED_CLUSTER_SHAPE_0, SG_TUNED_CLUSTER_SHAPE_1, SG_TUNED_CLUSTER_SHAPE_2)
162	prodigy_reduce_dsmem_kernel(
163	    const ParamT* param, const ParamT* param_init, const GradT* grad,
164	    float d_prev,
165	    float* r_partial, float* s_partial,
166	    int64_t N
167	) {
168	    // One shared slot per reduced quantity for this block's published partial.
169	    __shared__ float r_slot;
170	    __shared__ float s_slot;
171	
172	    float r_local = 0.0f, s_local = 0.0f;
173	    const int64_t stride = prim::grid_stride();
174	    for (int64_t i = prim::grid_stride_index(); i < N; i += stride) {
175	        SG_SANITIZE_GRAD_INPLACE(grad, i);
176	        prodigy_partials_step(param, param_init, grad, d_prev, i,
177	                              r_local, s_local);
178	    }
179	    // Full thread->warp->block->cluster tree; every block gets the same sum.
180	    float r_sum = prim::cluster_reduce_sum_f32_dsmem(r_local, &r_slot);
181	    float s_sum = prim::cluster_reduce_sum_f32_dsmem(s_local, &s_slot);
182	
183	    // One block (rank 0, thread 0) publishes the final result — no atomic.
184	    if (blockIdx.x == 0 && threadIdx.x == 0) {
185	        *r_partial = r_sum;
186	        *s_partial = s_sum;
187	    }
188	}
189	#endif  // ENABLE_DSMEM_REDUCE
190	
191	__global__ void prodigy_update_d_kernel(
192	    float* d_t, const float* r_sum, const float* s_sum, float d_prev
193	) {
194	    if (blockIdx.x == 0 && threadIdx.x == 0) {
195	        *d_t = prodigy_update_d(d_prev, *r_sum, *s_sum);
196	    }
197	}
